BEGIN;
create temp table assertion_count(n integer);insert into assertion_count values(0);
create function pg_temp.check_it(v boolean,label text)returns void language plpgsql as $$begin if v is distinct from true then raise exception 'Assertion failed: %',label;end if;update assertion_count set n=n+1;end$$;
create temp table st(k text primary key,v jsonb);
insert into public.properties(id,org_id,name)values('ee710000-0000-4000-8000-000000000001','22222222-2222-2222-2222-222222222222','Agency SQL fixture'),('ee710000-0000-4000-8000-000000000002','22222222-2222-2222-2222-222222222222','Other agency SQL fixture');
create function pg_temp.board(p uuid default'ee710000-0000-4000-8000-000000000001')returns jsonb language sql as $$select public.read_agency_observation(p,'11111111-1111-1111-1111-111111111111','{}')$$;
create function pg_temp.facts(product text default'siteforge')returns jsonb language sql as $$select public.agency_observation_evidence('ee710000-0000-4000-8000-000000000001','22222222-2222-2222-2222-222222222222',product)$$;
create function pg_temp.command()returns jsonb language sql as $$select jsonb_build_object('operation','review','product','siteforge','sourceHash',pg_temp.facts()->>'sourceHash','decision','investigate','reason','Private human review note')$$;
create function pg_temp.decide(i uuid,b jsonb,p uuid default'ee710000-0000-4000-8000-000000000001')returns jsonb language sql as $$select public.decide_agency_observation(i,p,'11111111-1111-1111-1111-111111111111',b)$$;
create function pg_temp.event(i uuid,product text,phase text,evidence text default'server_confirmed',at timestamptz default statement_timestamp()-interval'1 minute',p uuid default'ee710000-0000-4000-8000-000000000001',org uuid default'22222222-2222-2222-2222-222222222222')returns void language plpgsql as $$begin
 insert into public.shared_action_episodes(id,org_id,property_id,actor_id,origin)values(i,org,p,'11111111-1111-1111-1111-111111111111','console');
 insert into public.shared_action_events(id,episode_id,org_id,property_id,actor_id,product,action,evidence,phase,request,result,created_at)values(i,i,org,p,'11111111-1111-1111-1111-111111111111',product,'fixture.action',evidence,phase,'{"private":"secret request"}','{"private":"secret result"}',at);
end$$;
select pg_temp.check_it(jsonb_array_length(pg_temp.board()->'items')=19,'all scoped product families listed');
select pg_temp.check_it(pg_temp.facts()->>'confirmedCount'='0'and pg_temp.facts()->>'failedCount'='0','empty evidence stays empty');
select pg_temp.check_it(pg_temp.decide(gen_random_uuid(),pg_temp.command())->>'state'='no_recommendation','no invented recommendation');
select pg_temp.event(gen_random_uuid(),'siteforge','failed')from generate_series(1,7);
select pg_temp.event(gen_random_uuid(),'siteforge','succeeded');
select pg_temp.event(gen_random_uuid(),'siteforge','observed','browser_observed');
select pg_temp.event(gen_random_uuid(),'siteforge','failed','server_confirmed',statement_timestamp()-interval'8 days');
select pg_temp.event(gen_random_uuid(),'siteforge','failed','server_confirmed',statement_timestamp()+interval'1 day');
select pg_temp.event(gen_random_uuid(),'siteforge','failed','server_confirmed',statement_timestamp()-interval'1 minute','ee710000-0000-4000-8000-000000000002');
select pg_temp.check_it(pg_temp.facts()->>'confirmedCount'='8'and pg_temp.facts()->>'failedCount'='7'and pg_temp.facts()->>'observedCount'='1','complete counts exclude future old and other-property rows; successes do not hide failures');
select pg_temp.check_it(jsonb_array_length(pg_temp.facts()->'failures')=5,'failure display explicitly bounded');
select pg_temp.check_it(pg_temp.facts()::text not like '%secret%','source payloads excluded');
insert into st values('input',pg_temp.command());
select pg_temp.event(gen_random_uuid(),'siteforge','observed','browser_observed');
select pg_temp.check_it(pg_temp.facts()->>'sourceHash'=(select v->>'sourceHash'from st where k='input'),'browser observations do not invalidate review');
insert into st values('saved',pg_temp.decide('ee710000-0000-4000-8000-000000000010',(select v from st where k='input')));
select pg_temp.check_it(v->>'state'='saved'and v->'record'->'evidence'->>'failedCount'='7','exact reviewed evidence retained')from st where k='saved';
select pg_temp.check_it(pg_temp.decide('ee710000-0000-4000-8000-000000000010',(select v from st where k='input'))->>'state'='replayed','lost response is idempotent');
select pg_temp.check_it(pg_temp.decide('ee710000-0000-4000-8000-000000000010',(select v||'{"decision":"watch"}'from st where k='input'))->>'state'='request_conflict','same request cannot change choice');
select pg_temp.check_it(pg_temp.decide('ee710000-0000-4000-8000-000000000010',(select v from st where k='input'),'ee710000-0000-4000-8000-000000000002')->>'state'='request_conflict','same request cannot switch property');
select pg_temp.check_it((select count(*)=1 from public.shared_action_events where id='ee710000-0000-4000-8000-000000000010'),'one confirmed action per review');
select pg_temp.check_it((select request::text not like '%Private%'and result::text not like '%Private%'and not training_eligible and result->'executionAuthorized'='false'from public.shared_action_events where id='ee710000-0000-4000-8000-000000000010'),'notes excluded; no execution or training grant');
select pg_temp.check_it((select count(*)=0 from public.shared_jobs where property_id='ee710000-0000-4000-8000-000000000001'),'no execution jobs created');
select pg_temp.check_it((select count(*)=1 from jsonb_array_elements(pg_temp.board()->'items')i where i->'review'->>'id'='ee710000-0000-4000-8000-000000000010'),'current review attached to exact evidence');
select pg_temp.event(gen_random_uuid(),'siteforge','failed');
select pg_temp.check_it(pg_temp.decide(gen_random_uuid(),(select v from st where k='input'))->>'state'='evidence_changed','new activity rejects stale review');
select pg_temp.check_it(pg_temp.decide('ee710000-0000-4000-8000-000000000010',(select v from st where k='input'))->>'state'='replayed','saved decision remains recoverable after new evidence');
select pg_temp.check_it((select count(*)=0 from jsonb_array_elements(pg_temp.board()->'items')i where i->'review'<>'null'),'old review is not attached to changed evidence');
select pg_temp.check_it(pg_temp.decide('ee710000-0000-4000-8000-000000000011',pg_temp.command()||'{"decision":"watch"}')->>'state'='saved','corrected human decision saved separately');
select pg_temp.check_it((select count(*)=2 from public.agency_observation_reviews where property_id='ee710000-0000-4000-8000-000000000001'),'earlier review retained');
select pg_temp.check_it(pg_temp.decide(gen_random_uuid(),pg_temp.command()||'{"executeNow":true}')->>'state'='invalid','execution payload rejected');
select pg_temp.check_it(pg_temp.decide(gen_random_uuid(),pg_temp.command()||'{"reason":" "}')->>'state'='invalid','reason required');
select pg_temp.check_it(pg_temp.decide('ee710000-0000-4000-8000-000000000012',jsonb_build_object('operation','cancel_unused','inputHash',repeat('a',64)))->'record'->>'kind'='cancel_unused','unused request closed durably');
select pg_temp.check_it(pg_temp.decide('ee710000-0000-4000-8000-000000000012',pg_temp.command())->>'state'='decision_cancelled','late original request fenced');
select pg_temp.check_it(pg_temp.decide('ee710000-0000-4000-8000-000000000010',jsonb_build_object('operation','cancel_unused','inputHash',repeat('a',64)))->'record'->>'kind'='review','closing a saved request returns its review');
select pg_temp.check_it(public.read_agency_observation('ee710000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111','{"kind":"decision","decisionId":"ee710000-0000-4000-8000-000000000010"}')->>'state'='ready','saved receipt recoverable');
select pg_temp.check_it(public.read_agency_observation('ee710000-0000-4000-8000-000000000002','11111111-1111-1111-1111-111111111111','{"kind":"decision","decisionId":"ee710000-0000-4000-8000-000000000010"}')->>'state'='not_found','crossproperty receipt hidden');
select pg_temp.decide(gen_random_uuid(),pg_temp.command())from generate_series(1,21);
insert into st values('history',public.read_agency_observation('ee710000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111','{"kind":"history"}'));
select pg_temp.check_it(jsonb_array_length(v->'items')=20 and v->>'nextBefore' is not null,'complete paginated history offered')from st where k='history';
select pg_temp.check_it(jsonb_array_length(public.read_agency_observation('ee710000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111',jsonb_build_object('kind','history','before',(select v->>'nextBefore'from st where k='history')))->'items')=4,'older history has no gaps');
-- Recording failure must roll back the private review too.
create function pg_temp.fail_event()returns trigger language plpgsql as $$begin if new.product='agency'then raise exception 'fixture recording failure';end if;return new;end$$;
create trigger agency_fixture_failure before insert on public.shared_action_events for each row execute function pg_temp.fail_event();
do $$begin begin perform pg_temp.decide('ee710000-0000-4000-8000-000000000013',pg_temp.command());raise exception 'expected failure'using errcode='P0002';exception when sqlstate'P0001'then perform pg_temp.check_it(not exists(select 1 from public.agency_observation_reviews where id='ee710000-0000-4000-8000-000000000013'),'recording failure rolls back decision');end;end$$;
drop trigger agency_fixture_failure on public.shared_action_events;
do $$begin begin update public.agency_observation_reviews set reason='Overwritten'where id='ee710000-0000-4000-8000-000000000010';raise exception 'expected failure'using errcode='P0002';exception when sqlstate'55000'then perform pg_temp.check_it(true,'review history immutable');end;end$$;
select pg_temp.check_it(not has_table_privilege('authenticated','public.agency_observation_reviews','SELECT')and not has_table_privilege('anon','public.agency_observation_reviews','INSERT'),'no browser direct table access');
select pg_temp.check_it(not has_function_privilege('authenticated','public.decide_agency_observation(uuid,uuid,uuid,jsonb)','EXECUTE')and not has_function_privilege('anon','public.read_agency_observation(uuid,uuid,jsonb)','EXECUTE'),'no anonymous or browser direct RPC access');
update public.profiles set role='viewer'where id='11111111-1111-1111-1111-111111111111';
select pg_temp.check_it(pg_temp.board()->'canManage'='false','viewer sees read-only review');
select pg_temp.check_it(pg_temp.decide(gen_random_uuid(),pg_temp.command())->>'state'='forbidden','current viewer cannot decide');
select pg_temp.check_it(pg_temp.decide('ee710000-0000-4000-8000-000000000010',(select v from st where k='input'))->>'state'='forbidden','removed manager cannot replay mutation');
insert into public.organizations(id,name)values('ee710000-0000-4000-8000-000000000090','Agency transferred org');
select set_config('p11.team_scope','22222222-2222-2222-2222-222222222222',true);
update public.profiles set org_id='ee710000-0000-4000-8000-000000000090',role='admin'where id='11111111-1111-1111-1111-111111111111';
select pg_temp.check_it(pg_temp.board()->>'state'='forbidden','removed member cannot read old property');
-- Owner change must not import former tenant evidence or notes.
set local session_replication_role=replica;
update public.properties set org_id='ee710000-0000-4000-8000-000000000090'where id='ee710000-0000-4000-8000-000000000001';
set local session_replication_role=origin;
select pg_temp.check_it((select bool_and(i->'evidence'->>'confirmedCount'='0'and i->'review'='null')from jsonb_array_elements(pg_temp.board()->'items')i),'transferred property excludes earlier tenant evidence');
select pg_temp.check_it(jsonb_array_length(public.read_agency_observation('ee710000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111','{"kind":"history"}')->'items')=0,'former tenant review notes hidden');
select 'Agency observation assertions: '||n from assertion_count;
ROLLBACK;
